  let dlgOr=null;
  const st=()=>({});
  function drawTeste(){testEl.innerHTML=testeaza(Q,doc,st()).map(t=>`<li class="${t.ok?'ok':''}"><span class="ic" aria-hidden="true">${t.ok?'✔':'○'}</span><span>${esc(t.ce)}${t.ok?'<span class="sr-only"> — gata</span>':''}</span></li>`).join('')}
