    const r=lo.getBoundingClientRect(),pr=pagEl.getBoundingClientRect(),dr=Math.min(pr.right,innerWidth)-6,st=Math.max(pr.left,0)+6;
    if(r.right>dr)pagEl.scrollLeft+=r.right-dr;else if(r.left<st)pagEl.scrollLeft-=st-r.left;
